import{_ as s,C as o,o as r,c as n,j as t,a as l,E as i,a2 as u}from"./chunks/framework.BxGh02fV.js";const q=JSON.parse('{"title":"Tâches","description":"","frontmatter":{"title":"Tâches"},"headers":[],"relativePath":"guide/tasks.md","filePath":"guide/tasks.md"}'),c={name:"guide/tasks.md"};function d(h,e,g,p,v,f){const a=o("Capture");return r(),n("div",null,[e[0]||(e[0]=t("h1",{id:"taches",tabindex:"-1"},[l("Tâches "),t("a",{class:"header-anchor",href:"#taches","aria-label":'Permalink to "Tâches"'},"​")],-1)),e[1]||(e[1]=t("p",null,"Cet écran liste les tâches de la story active et permet d'en ajouter. Vous y venez pour suivre l'avancement du travail en cours et changer l'état d'une tâche.",-1)),i(a,{name:"taches",alt:"L'écran Tâches : trois tâches de la story active et le formulaire Nouvelle tâche"}),e[2]||(e[2]=u('<h2 id="ce-que-vous-voyez" tabindex="-1">Ce que vous voyez <a class="header-anchor" href="#ce-que-vous-voyez" aria-label="Permalink to &quot;Ce que vous voyez&quot;">​</a></h2><ul><li><strong>Tâches</strong> (colonne de gauche) : une carte par tâche de la story active. <ul><li>La référence de la tâche (par exemple <code>26E2S1T1</code>), son état (<strong>À faire</strong>, <strong>En cours</strong> ou <strong>Terminée</strong>) et sa phase OPALE (par exemple <code>O-analyse</code>).</li><li>Le titre en gras, puis la description.</li><li>Une liste déroulante pour changer l&#39;état.</li></ul></li><li><strong>Nouvelle tâche</strong> (colonne de droite) : le formulaire d&#39;ajout, avec les champs <strong>Titre</strong> et <strong>Description</strong>.</li></ul><p>Si aucune story n&#39;est active, l&#39;écran affiche « Aucune story active » et un bouton <strong>Aller au backlog</strong> : activez d&#39;abord une story depuis le <a href="/Effortless/guide/backlog.html">Backlog</a>. Si la story n&#39;a pas encore de tâche, la liste affiche « Aucune tâche pour cette story. »</p><h2 id="ce-que-vous-pouvez-faire" tabindex="-1">Ce que vous pouvez faire <a class="header-anchor" href="#ce-que-vous-pouvez-faire" aria-label="Permalink to &quot;Ce que vous pouvez faire&quot;">​</a></h2><h3 id="changer-l-etat-d-une-tache" tabindex="-1">Changer l&#39;état d&#39;une tâche <a class="header-anchor" href="#changer-l-etat-d-une-tache" aria-label="Permalink to &quot;Changer l&#39;état d&#39;une tâche&quot;">​</a></h3><p>Ouvrez la liste déroulante à droite de la carte et choisissez <strong>À faire</strong>, <strong>En cours</strong> ou <strong>Terminée</strong>. Le changement est enregistré tout de suite et la liste se recharge. Passez à <strong>En cours</strong> la tâche sur laquelle vous codez : tant qu&#39;au moins une tâche du projet est <strong>En cours</strong>, le détecteur de <a href="/Effortless/guide/drift.html">Dérive</a> considère qu&#39;il y a une tâche active. Il ne regarde pas laquelle : c&#39;est à vous de garder l&#39;état de vos tâches juste.</p><h3 id="ajouter-une-tache" tabindex="-1">Ajouter une tâche <a class="header-anchor" href="#ajouter-une-tache" aria-label="Permalink to &quot;Ajouter une tâche&quot;">​</a></h3><ol><li>Saisissez un <strong>Titre</strong>. Il est obligatoire : sans titre, rien n&#39;est créé.</li><li>Ajoutez si vous le voulez une <strong>Description</strong>.</li><li>Cliquez sur <strong>Ajouter la tâche</strong>.</li></ol><p>La nouvelle tâche reçoit la phase courante de la story et apparaît dans la liste.</p><h2 id="conseils" tabindex="-1">Conseils <a class="header-anchor" href="#conseils" aria-label="Permalink to &quot;Conseils&quot;">​</a></h2><ul><li>Une story ne peut se clore que lorsque toutes ses tâches sont <strong>Terminée</strong>.</li><li>Si l&#39;auto-commit des métadonnées est activé (voir <a href="/Effortless/guide/git.html">Git</a>), chaque ajout ou changement d&#39;état est committé automatiquement.</li></ul><h2 id="avec-un-agent-ia" tabindex="-1">Avec un agent IA <a class="header-anchor" href="#avec-un-agent-ia" aria-label="Permalink to &quot;Avec un agent IA&quot;">​</a></h2><p>Un agent fait la même chose par le serveur MCP : <code>effortless_task_add</code> crée une tâche, <code>effortless_task_update</code> change son état, et <code>effortless_story_items</code> liste les tâches d&#39;une story. L&#39;écran affiche simplement le résultat de leur travail.</p>',13))])}const _=s(c,[["render",d]]);export{q as __pageData,_ as default};
